package android.net;import java.util.*;public class ConnectivityManager {public boolean wifi;public final List<NetworkCallback> callbacks=new ArrayList<>();public Network[] getAllNetworks(){return wifi?new Network[]{new Network(1)}:new Network[0];}public NetworkCapabilities getNetworkCapabilities(Network n){return new NetworkCapabilities(1);}public void registerNetworkCallback(NetworkRequest r,NetworkCallback c){callbacks.add(c);}public static class NetworkCallback {public void onAvailable(Network n){}}public void available(){wifi=true;for(NetworkCallback c:callbacks)c.onAvailable(new Network(1));}}
